import React from 'react';
import { Link } from 'react-router-dom';
import '../assets/styles/Home.css'; // Importing the CSS file for styling

// Home component displays the welcome message and navigation buttons
const Home = () => {
  return (
    <div className="home">
      {/* Main heading */}
      <h1>Welcome to My Portfolio</h1>

      {/* Mission statement and personal introduction */}
      <p className="mission">
      
Hello! I'm Gladys Pineda Ospina,  I am an Ambitious and motivated Software Engineering Technology , AI student at Centennial College  with a passion for creating efficient, innovative solutions. This page showcases my skills, projects, and experiences that demonstrate my ability to deliver results in real-world scenarios.

About Me
I have a strong foundation in Python, JavaScript, C#, SQL, and web application development. Experienced in both front-end and back-end programming, database management, and the software development lifecycle, with hands-on exposure to multi-tiered architectures, testing, and Agile methods.  and enjoy solving challenging problems through creative and practical approaches. My work reflects a commitment to quality, collaboration, and continuous learning.

Feel free to explore my projects and experiences, and don't hesitate to reach out if you'd like to discuss potential opportunities.
      </p>

      {/* Navigation buttons to other pages */}
      <div className="home-buttons">
        <Link to="/about" className="btn">About Me</Link>
        <Link to="/projects" className="btn">View Projects</Link>
      </div>
    </div>
  );
};

export default Home;
